root.structure.line.kernel.enc.adc.heade.script:
if (scheme == 'Phase') or (scheme == 'Phase-Slice') or (scheme == 'Slice-Phase')
  or (scheme == 'Interleaved-Slice-Phase') or (scheme == 'Interleaved-Phase-Slice') then
  return {0, acq_size['phase']['size']-1, line_center['phase']}
end
return {0, 0, 0}

if (scheme == 'Phase-Slice') or (scheme == 'Slice-Phase')
  or (scheme == 'Interleaved-Slice-Phase') or (scheme == 'Interleaved-Phase-Slice') then
  return {0, acq_size['slice']['size']-1, line_center['slice']}
end
return {0, 0, 0}

local vec2 = orientation[2][1]*orientation[2][1] + orientation[2][2]*orientation[2][2] + orientation[2][3]*orientation[2][3]
local length = math.sqrt(vec2)
return {orientation[2][1]/length, orientation[2][2]/length, orientation[2][3]/length}

local vec2 = orientation[1][1]*orientation[1][1] + orientation[1][2]*orientation[1][2] + orientation[1][3]*orientation[1][3]
local length = math.sqrt(vec2)
return {orientation[1][1]/length, orientation[1][2]/length, orientation[1][3]/length}

local vec2 = orientation[3][1]*orientation[3][1] + orientation[3][2]*orientation[3][2] + orientation[3][3]*orientation[3][3]
local length = math.sqrt(vec2)
return {orientation[3][1]/length, orientation[3][2]/length, orientation[3][3]/length}

if pos == #reorder['lines']-1 then
  return {phase=-1, slice=-1, read=-1}
elseif reorder['lines'][1+pos+1] ~= nil then
  local phase = reorder['lines'][1+pos+1]['pos']['phase']
  local slice = reorder['lines'][1+pos+1]['pos']['slice']
  local read = reorder['lines'][1+pos+1]['pos']['read']
  return {phase=phase, slice=slice, read=read}
end
return {phase=-1,slice=-1,read=-1}

if pos == 0 then
  return {phase=-1, slice=-1, read=-1}
elseif reorder['lines'][1+pos-1] ~= nil then
  local phase = reorder['lines'][1+pos-1]['pos']['phase']
  local slice = reorder['lines'][1+pos-1]['pos']['slice']
  local read = reorder['lines'][1+pos-1]['pos']['read']
  return {phase=phase, slice=slice, read=read}
end
return {phase=-1, slice=-1, read=-1}

if (seq_dim == 2) then
  return mb_factor * num_lines * fov * (1+DF)
end
return fov * (1+os)
